1	export function addTodo(items, title, id) {
2	  const cleaned = title.trim();
3	  if (!cleaned || cleaned.length > 100) return items;
4	  return [...items, { id, title: cleaned, completed: false }];
5	}
6	export function toggleTodo(items, id) {
7	  return items.map(item => item.id === id ? { ...item, completed: !item.completed } : item);
8	}
9	export function removeTodo(items, id) {
10	  return items.filter(item => item.id !== id);
11	}
12

1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { addTodo, toggleTodo, removeTodo } from '../model.js';
4	
5	test('新增待辦會去除前後空白並保留既有資料', () => {
6	  const original = [{ id: 'a', title: '買早餐', completed: true }];
7	  const added = addTodo(original, '  讀書  ', 'b');
8	  assert.deepEqual(added, [...original, { id: 'b', title: '讀書', completed: false }]);
9	  assert.equal(original.length, 1);
10	});
11	test('拒絕空白與過長內容', () => {
12	  const original = [];
13	  assert.equal(addTodo(original, '   ', 'a'), original);
14	  assert.equal(addTodo(original, '字'.repeat(101), 'a'), original);
15	});
16	test('依照識別碼切換指定項目，不改動其他項目', () => {
17	  const original = [{ id: 'a', title: '相同標題', completed: false }, { id: 'b', title: '相同標題', completed: true }];
18	  const updated = toggleTodo(original, 'a');
19	  assert.equal(updated[0].completed, true);
20	  assert.equal(updated[1].completed, true);
21	  assert.equal(original[0].completed, false);
22	});
23	test('刪除依識別碼進行，找不到項目時仍保留資料', () => {
24	  const original = [{ id: 'a', title: '測試', completed: false }];
25	  assert.deepEqual(removeTodo(original, 'missing'), original);
26	  assert.deepEqual(removeTodo(original, 'a'), []);
27	});
